using Object=UnityEngine.Object;
using C2=CrabCityDensityR2;

public static class BoutiqueModelPreviewR18 {
 static string Dir=>Path.GetFullPath(Path.Combine(Application.dataPath,"../ModelReviews/MallObjectR18Review"));
 [Serializable]public class ModelRow{public string model;public int renderers,submeshDraws,triangles,vertices,lights;public float boundsExpansion;}
 [Serializable]public class Report{public string revision=MallModelPackR18.Revision,state="RUNNING",inputCommit="4ff3e341c228592a0cd152eb413b751e9d18d575",method="Game-camera rendering with the unmodified r17 crab and a deliberately positioned existing real collision fixture. Not natural reach, browser input or a new physics fix.";public List<ModelRow> models=new List<ModelRow>();public string colliderBefore,colliderAfter,bodyBefore,bodyAfter,breakState;public int boundObjects;public bool noNewPhysics,bodyUnchanged,actualTargetBreak;public List<string> frames=new List<string>();}
 public static void Run(){Directory.CreateDirectory(Dir);var report=new Report();CrabFlightGame g=null;
  try{
   g=Game();report.models=Audit();g.BeginSpinCharge("");for(int i=0;i<601;i++){g.AddSpinWork(JsonUtility.ToJson(new SpinWorkInput{distance=2f/60,seconds=1f/60,direction=1}));g.Tick(1f/60);}g.BeginAim("");g.ReleaseLaunch(JsonUtility.ToJson(new FlightAimInput{angle=12,power=100,direction=1,eligible=true}));var sim=g.ReviewSimulation;
   const string target="street3-+1-10-market_stall";sim.ReviewRouteSegmentR11(target);for(int i=0;i<14&&sim.Body.position.x<66.3f;i++)g.Tick(1f/120);g.SetPaused("1");
   var cam=g.ReviewCamera;cam.aspect=844f/390;g.RefreshReviewCamera();var cp=cam.transform.position;var cr=cam.transform.rotation;float cs=cam.orthographicSize;
   Capture(cam,"game-r17-before-models.png",1688,780);report.frames.Add("game-r17-before-models.png");report.colliderBefore=ColliderFingerprint(sim.Scene);report.bodyBefore=Body(sim.Body);
   foreach(var root in sim.Scene.GetRootGameObjects())report.boundObjects+=MallModelPackR18.ApplyToRoot(root);var bay=MallModelPackR18.AddBay(g.transform);report.colliderAfter=ColliderFingerprint(sim.Scene);report.bodyAfter=Body(sim.Body);report.bodyUnchanged=report.bodyBefore==report.bodyAfter;report.noNewPhysics=bay.GetComponentsInChildren<Collider>(true).Length==0&&bay.GetComponentsInChildren<Rigidbody>(true).Length==0&&report.colliderBefore==report.colliderAfter;
   Capture(cam,"game-models-intact.png",1688,780);Capture(cam,"game-models-intact-844.png",844,390);report.frames.Add("game-models-intact.png");report.frames.Add("game-models-intact-844.png");
   cam.aspect=390f/844;g.RefreshReviewCamera();Capture(cam,"game-models-portrait.png",390,844);report.frames.Add("game-models-portrait.png");cam.aspect=844f/390;cam.transform.SetPositionAndRotation(cp,cr);cam.orthographicSize=cs;
   g.SetPaused("0");for(int i=0;i<160&&!g.Finished&&!report.actualTargetBreak;i++){g.Tick(1f/120);report.actualTargetBreak=sim.BreakEvents.Any(x=>x.id==target);}for(int i=0;i<7&&!g.Finished;i++)g.Tick(1f/120);g.SetPaused("1");
   cam.transform.SetPositionAndRotation(cp,cr);cam.orthographicSize=cs;Capture(cam,"game-models-after-contact.png",1688,780);Capture(cam,"game-models-after-contact-844.png",844,390);report.frames.Add("game-models-after-contact.png");report.breakState=JsonUtility.ToJson(g.State());
   File.WriteAllText(Path.Combine(Dir,"break-events.json"),JsonUtility.ToJson(new EventRows{events=sim.BreakEvents.ToArray()},true));File.WriteAllText(Path.Combine(Dir,"after-contact-state.json"),JsonUtility.ToJson(g.State(),true));
   if(!report.noNewPhysics||!report.bodyUnchanged||report.boundObjects!=3)throw new Exception("Model adapter changed host physical state");
   if(!report.actualTargetBreak)throw new Exception("Target did not break in the actual existing collision fixture");
   g.ShutdownReviewPhysics();g=null;Showcase(report);report.state="COMPLETED";
  }finally{if(g)g.ShutdownReviewPhysics();File.WriteAllText(Path.Combine(Dir,"model-review.json"),JsonUtility.ToJson(report,true));}
 }
 public static void BuildAndReview(){BoutiqueModelBuilderR18.BuildAll();Run();}
 [Serializable]class EventRows{public WorldBreakEvent[] events;}
 static CrabFlightGame Game(){CrabModel.ReviewUseBaseline(false);((IDictionary)typeof(DistrictWorldArtR9).GetField("cache",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null)).Clear();EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var g=new GameObject("R18 preview r17 subject").AddComponent<CrabFlightGame>();g.enabled=false;g.crabShader=Shader.Find("CustomCrabBattle/ChitinR3");g.groundShader=Shader.Find("Standard");g.cityLayout=2;g.cityR2Shader=Shader.Find("CrabCityDensity/R2Surface");g.cityR2Albedo=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/CrabCityDensityR2/Textures/CityAlbedoAtlas.png");g.cityR2Metal=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/CrabCityDensityR2/Textures/CityMetalSmoothAtlas.png");g.fragmentFadeShader=AssetDatabase.LoadAssetAtPath<Shader>("Assets/CrabCityDensityR2/Shaders/BrokenMetalVisibility.shader");g.effectsPrefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/CrabVfxPack/Prefabs/CrabDestructionVfx.prefab").GetComponent<CrabDestructionVfx.CrabVfxRig>();EditorSceneManager.SaveScene(SceneManager.GetActiveScene(),"Assets/MallModelPackR18/Editor/PreviewSession.unity");g.Initialize();return g;}
 static List<ModelRow> Audit(){var rows=new List<ModelRow>();foreach(string name in new[]{"FragranceCase","FragranceDisplay","BoutiqueEntrance","BoutiqueBay","Product_RoundFlacon","Product_SquareFlacon"}){
  var p=Resources.Load<GameObject>("MallModelsR18/"+name);if(!p)throw new Exception("Missing model "+name);var row=new ModelRow{model=name,renderers=p.GetComponentsInChildren<MeshRenderer>(true).Length,lights=p.GetComponentsInChildren<Light>(true).Length};foreach(var f in p.GetComponentsInChildren<MeshFilter>(true)){row.vertices+=f.sharedMesh.vertexCount;row.triangles+=f.sharedMesh.triangles.Length/3;row.submeshDraws+=f.sharedMesh.subMeshCount;}
  string donor=name=="FragranceCase"?"market_stall":name=="FragranceDisplay"?"market_crate":name=="BoutiqueEntrance"?"street_awning":null;
  if(donor!=null){var asset=City2Data.Asset(donor);foreach(Transform part in p.transform){if(!part.name.StartsWith("Part_"))continue;int shard=int.Parse(part.name.Substring(5));var old=asset.pieces.Where(x=>x.shard==shard).Select(City2Data.Bounds).ToArray();var bounds=old[0];foreach(var a in old)bounds.Encapsulate(a);foreach(var f in part.GetComponentsInChildren<MeshFilter>()){var a=f.sharedMesh.bounds;row.boundsExpansion=Mathf.Max(row.boundsExpansion,Mathf.Max(0,bounds.min.x-a.min.x,bounds.min.y-a.min.y,bounds.min.z-a.min.z,a.max.x-bounds.max.x,a.max.y-bounds.max.y,a.max.z-bounds.max.z));}}if(row.boundsExpansion>.0001f)throw new Exception("Model expanded existing shard envelope: "+name+" "+row.boundsExpansion);}
  if(p.GetComponentsInChildren<Collider>(true).Length>0||p.GetComponentsInChildren<Rigidbody>(true).Length>0)throw new Exception("New model contains physics components");rows.Add(row);
 }return rows;}
 static string ColliderFingerprint(Scene scene){var lines=new List<string>();foreach(var root in scene.GetRootGameObjects())foreach(var c in root.GetComponentsInChildren<BoxCollider>(true))lines.Add(c.name+"|"+c.center.ToString("R")+"|"+c.size.ToString("R")+"|"+c.transform.position.ToString("R")+"|"+c.transform.rotation.ToString("R")+"|"+c.transform.lossyScale.ToString("R")+"|"+c.enabled);lines.Sort(StringComparer.Ordinal);using(var h=System.Security.Cryptography.SHA256.Create())return string.Concat(h.ComputeHash(Encoding.UTF8.GetBytes(string.Join("\n",lines))).Select(x=>x.ToString("x2")));}
 static string Body(Rigidbody body){return body.position.ToString("R")+"|"+body.rotation.ToString("R")+"|"+body.linearVelocity.ToString("R")+"|"+body.angularVelocity.ToString("R")+"|"+body.mass.ToString("R");}
 static void Showcase(Report report){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);Lighting();var bay=Object.Instantiate(Resources.Load<GameObject>("MallModelsR18/BoutiqueBay"));bay.name="BoutiqueBay";foreach(var pair in new[]{new Vector2(-5,0),new Vector2(0,1),new Vector2(5,2)}){string name=pair.y==0?"FragranceCase":pair.y==1?"FragranceDisplay":"BoutiqueEntrance";var p=Object.Instantiate(Resources.Load<GameObject>("MallModelsR18/"+name));p.name=name;p.transform.position=new Vector3(pair.x,0,0);}
  var cam=new GameObject("Asset inspection camera").AddComponent<Camera>();cam.orthographic=true;cam.orthographicSize=5.2f;cam.nearClipPlane=.1f;cam.farClipPlane=100;cam.backgroundColor=new Color(.13f,.19f,.22f);cam.clearFlags=CameraClearFlags.SolidColor;cam.transform.position=new Vector3(3.5f,5.5f,-14);cam.transform.LookAt(new Vector3(0,2.3f,0));Capture(cam,"model-set-inspection.png",1688,980);report.frames.Add("model-set-inspection.png");EditorSceneManager.SaveScene(SceneManager.GetActiveScene(),"Assets/MallModelPackR18/Showcase.unity");
  foreach(string name in new[]{"FragranceCase","FragranceDisplay","BoutiqueEntrance"}){var model=GameObject.Find(name);foreach(var r in Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None))r.enabled=r.transform.IsChildOf(model.transform);cam.orthographicSize=name=="BoutiqueEntrance"?3.6f:2.65f;cam.transform.position=model.transform.position+new Vector3(3.4f,3.0f,-7.5f);cam.transform.LookAt(model.transform.position+Vector3.up*(name=="BoutiqueEntrance"?2.5f:1.8f));Capture(cam,"model-"+name+".png",1100,900);report.frames.Add("model-"+name+".png");}
 }
 static void Lighting(){RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.45f,.52f,.60f);RenderSettings.ambientEquatorColor=new Color(.34f,.38f,.39f);RenderSettings.ambientGroundColor=new Color(.32f,.29f,.25f);var sun=new GameObject("R17 matching sun").AddComponent<Light>();sun.type=LightType.Directional;sun.color=new Color(1,.93f,.78f);sun.intensity=1.35f;sun.transform.rotation=Quaternion.Euler(48,-35,0);var fill=new GameObject("R17 matching fill").AddComponent<Light>();fill.type=LightType.Directional;fill.color=new Color(.7f,.8f,.9f);fill.intensity=.38f;fill.shadows=LightShadows.None;fill.transform.rotation=Quaternion.Euler(-32,135,0);}
 static void Capture(Camera camera,string name,int width,int height){camera.aspect=(float)width/height;var old=RenderTexture.active;var rt=new RenderTexture(width,height,24);camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var t=new Texture2D(width,height,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,width,height),0,0);t.Apply();File.WriteAllBytes(Path.Combine(Dir,name),t.EncodeToPNG());camera.targetTexture=null;RenderTexture.active=old;Object.DestroyImmediate(t);Object.DestroyImmediate(rt);}
}
